'use client'

import {
  type LibraryModel,
  listLibrary,
  S,
  usePlaceModel,
  useSceneUsage,
  watchLibrary,
  workerHint,
} from '@lustefaniak/pascal-studio-core'
import { type AnyNodeId, useScene } from '@pascal-app/core'
import { useCallback, useEffect, useRef, useState } from 'react'

/**
 * The project's own models.
 *
 * These are made, not collected — typically generated by a project's own
 * scripts — so the panel is built around a model changing under it rather
 * than being a fixed catalog. The worker watches the configured directories
 * and this list follows along; models already placed in the scene are a
 * separate, explicit step, because swapping a mesh someone is working against
 * should not happen behind their back.
 */
export default function LibraryPanel() {
  const [models, setModels] = useState<LibraryModel[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [query, setQuery] = useState('')
  const [stale, setStale] = useState<LibraryModel[]>([])
  const place = usePlaceModel()
  const usage = useSceneUsage()
  const nodes = useScene((state) => state.nodes)
  const fingerprint = useRef('')

  const reload = useCallback(async () => {
    try {
      const data = await listLibrary()
      fingerprint.current = data.fingerprint
      setModels(data.models)
      setError(null)
      return data.models
    } catch (cause) {
      setError(workerHint(cause))
      return null
    }
  }, [])

  useEffect(() => {
    void reload()
  }, [reload])

  // Follow the watched directories. Each poll parks on the worker until
  // something actually changes, so an idle panel costs one open request.
  useEffect(() => {
    const controller = new AbortController()
    let stopped = false
    const follow = async () => {
      while (!stopped) {
        try {
          const result = await watchLibrary(fingerprint.current, controller.signal)
          if (stopped) return
          if (result.changed) await reload()
          else fingerprint.current = result.fingerprint
        } catch {
          if (stopped) return
          await new Promise((resolve) => setTimeout(resolve, 3000))
        }
      }
    }
    void follow()
    return () => {
      stopped = true
      controller.abort()
    }
  }, [reload])

  // Which placed items point at an older build of a model than the one on disk.
  useEffect(() => {
    if (!models) return
    const placed = new Map<string, string>()
    for (const node of Object.values(
      nodes as Record<string, { type?: string; asset?: { src?: string } }>,
    )) {
      const src = node?.type === 'item' ? node.asset?.src : undefined
      if (src) placed.set(src.replace(/^https?:\/\/[^/]+\//, '').split('?')[0]!, src)
    }
    setStale(
      models.filter((model) => {
        const current = placed.get(model.path)
        return current !== undefined && current !== model.url
      }),
    )
  }, [models, nodes])

  /**
   * Re-point placed items at the current file. The URL carries the mtime, so
   * this is what actually makes the loader fetch a regenerated model — the
   * cache is keyed by URL and would otherwise serve the old mesh forever.
   */
  const refreshPlaced = () => {
    const byPath = new Map(stale.map((model) => [model.path, model]))
    for (const [id, node] of Object.entries(
      nodes as Record<string, { type?: string; asset?: { src?: string } }>,
    )) {
      const src = node?.type === 'item' ? node.asset?.src : undefined
      if (!src) continue
      const model = byPath.get(src.replace(/^https?:\/\/[^/]+\//, '').split('?')[0]!)
      if (!model) continue
      useScene.getState().updateNode(
        id as AnyNodeId,
        {
          asset: { ...(node as { asset: object }).asset, src: model.url },
        } as never,
      )
    }
    setStale([])
  }

  const needle = query.trim().toLowerCase()
  const shown = (models ?? []).filter(
    (model) =>
      !needle ||
      model.name.toLowerCase().includes(needle) ||
      model.tags.some((tag) => tag.toLowerCase().includes(needle)),
  )

  return (
    <div style={S.body}>
      <div style={S.row}>
        <input
          onChange={(event) => setQuery(event.target.value)}
          placeholder="filter by name or tag"
          style={S.input}
          value={query}
        />
        <button onClick={() => void reload()} style={S.small} type="button">
          Refresh
        </button>
      </div>

      {stale.length > 0 ? (
        <div style={{ ...S.item, flexDirection: 'column', alignItems: 'stretch', gap: 6 }}>
          <span style={S.muted}>
            {stale.length} model(s) in the scene are older than the file on disk.
          </span>
          <button onClick={refreshPlaced} style={S.small} type="button">
            Reload models in the scene
          </button>
        </div>
      ) : null}

      {error ? <p style={S.error}>{error}</p> : null}

      <ul style={S.list}>
        {shown.map((model) => {
          const placed = usage.get(model.path) ?? 0
          return (
            <li key={model.path} style={S.item}>
              <span style={S.itemMain}>
                <strong style={S.itemTitle}>{model.name}</strong>
                <span style={S.muted}>
                  {model.dimensions
                    ? `${model.dimensions.map((value) => value.toFixed(2)).join(' × ')} m`
                    : 'dimensions unknown'}
                  {` · ${(model.sizeBytes / 1024).toFixed(0)} kB`}
                  {model.source && model.source !== 'local' ? ` · ${model.source}` : ''}
                </span>
              </span>
              {placed > 0 ? <span style={S.badge}>in scene ×{placed}</span> : null}
              <button onClick={() => place(model)} style={S.small} type="button">
                Place
              </button>
            </li>
          )
        })}
        {models && shown.length === 0 ? <p style={S.muted}>Nothing matches.</p> : null}
      </ul>
    </div>
  )
}
